/** 답가 음성의 전사 초안 API입니다. */
package com.dandimate.durooduroo.scroll.controller;
import com.dandimate.durooduroo.ai.service.OpenAiTranscriptionService; import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.auth.MemberTokenResolver; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.repository.MemberRepository; import com.dandimate.durooduroo.scroll.repository.ParagraphRepository; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.time.LocalDateTime; import java.util.*;
@RestController public class ParagraphTranscriptionController {private final ParagraphRepository paragraphs;private final MemberRepository members;private final OpenAiTranscriptionService stt;private final com.dandimate.durooduroo.room.service.RoomStateService roomStates;public ParagraphTranscriptionController(ParagraphRepository p,MemberRepository m,OpenAiTranscriptionService s,com.dandimate.durooduroo.room.service.RoomStateService roomStates){paragraphs=p;members=m;stt=s;this.roomStates=roomStates;}@PostMapping(value="/api/v1/paragraphs/{paragraphId}/transcriptions",consumes="multipart/form-data")public ApiResponse<?> transcribe(@PathVariable String paragraphId,@RequestHeader(required=false) String authorization,@RequestPart MultipartFile file){var p=paragraphs.findById(paragraphId).orElseThrow(()->new BusinessException("PARAGRAPH_NOT_FOUND","문단이 없습니다."));String token=MemberTokenResolver.resolve(authorization);members.findByRoomIdAndMemberToken(p.getRoomId(),token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","참여자만 사용할 수 있습니다."));roomStates.require(p.getRoomId(),com.dandimate.durooduroo.room.domain.RoomAction.REPLY);if(file.isEmpty())throw new BusinessException("INVALID_AUDIO","음성 파일이 비어 있습니다.");return ApiResponse.success(Map.of("transcriptionId",UUID.randomUUID().toString(),"audioAssetId",UUID.randomUUID().toString(),"transcript",stt.transcribe(file),"detectedLanguages",List.of("ko"),"expiresAt",LocalDateTime.now().plusHours(24)));}}
